import assert from 'node:assert/strict';import{performance}from'node:perf_hooks';
import{initDatabase,getDb,closeDatabase}from'../../src/db/connection.js';import{storeToolOutputWithChunks}from'../../src/db/tool-outputs.js';
initDatabase();const db=getDb();try{
 db.transaction(()=>{for(let n=0;n<1000;n++)storeToolOutputWithChunks({id:'output-'+n,created_at:'2999-01-01T00:00:00.000Z'},Array.from({length:10},(_,k)=>'common marker'+n+' synthetic chunk '+k))}).immediate();
 const queries=[{name:'baseline',sql:"SELECT snippet(tool_outputs_fts,0,'[',']','…',12) AS snippet FROM tool_outputs_fts WHERE tool_outputs_fts MATCH ? AND output_id=? LIMIT ?",params:['common','output-999',5]},{name:'rowid-subquery',sql:"SELECT snippet(tool_outputs_fts,0,'[',']','…',12) AS snippet FROM tool_outputs_fts WHERE tool_outputs_fts MATCH ? AND rowid IN(SELECT rowid FROM tool_outputs_fts WHERE output_id=?) LIMIT ?",params:['common','output-999',5]},{name:'materialized-target',sql:"WITH target AS MATERIALIZED (SELECT rowid FROM tool_outputs_fts WHERE output_id=?) SELECT snippet(tool_outputs_fts,0,'[',']','…',12) AS snippet FROM target CROSS JOIN tool_outputs_fts ON tool_outputs_fts.rowid=target.rowid WHERE tool_outputs_fts MATCH ? LIMIT ?",params:['output-999','common',5]}];
 const rows=[];for(const q of queries){const statement=db.prepare(q.sql);const start=performance.now();for(let n=0;n<100;n++){const r=statement.all(...q.params)as any[];assert.equal(r.length,5);assert(r.every(x=>x.snippet.includes('marker999')))}rows.push({name:q.name,ms:performance.now()-start,plan:db.query('EXPLAIN QUERY PLAN '+q.sql).all(...q.params)})}console.log(JSON.stringify(rows));
}finally{closeDatabase()}
